INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196000,'28079','Chueca','lgtbi','lgtbi_wiki','Chueca es una zona del barrio de Justicia, en el distrito Centro de la ciudad española de Madrid. Carece de entidad administrativa. Toma su nombre de la plaza y el metro de Chueca, dedicados al compositor Federico Chueca, y queda limitada al norte por la calle de Fernando VI, al sur por la Gran Vía, al este por la…',40.42166667,-3.69805556,'https://es.wikipedia.org/wiki/Chueca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196001,'08003','Gaixample','lgtbi','lgtbi_wiki','El Gayxample o Gaixample (de los términos en inglés gay y ensanche, en catalán gai y Eixample) es el nombre con el que se conoce popularmente una zona céntrica en el Distrito del Ensanche de Barcelona (España), en el que, desde finales del siglo XX, han ido proliferando los comercios y locales de ocio orientados al…',NULL,NULL,'https://es.wikipedia.org/wiki/Gaixample');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196002,'08003','Circuit Festival','lgtbi','lgtbi_wiki','Circuit Festival —también conocido como Circuit Festival Barcelona— es un festival internacional de gays y lesbianas que se celebra anualmente en Barcelona desde 2008. Es el mayor festival de ocio de estas características que se celebra en Europa cada año.​ En la edición de 2012 la asistencia fue de 70 000 personas…',NULL,NULL,'https://es.wikipedia.org/wiki/Circuit_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196003,'28079','Orgullo de Madrid','lgtbi','lgtbi_wiki','Las Fiestas del Orgullo de Madrid, conocidas popularmente como el Orgullo LGTB​ de Madrid y por su acrónimo MADO (Madrid Orgullo),​ son las fiestas celebradas por el barrio de Chueca, en el centro de Madrid el fin de semana posterior al 28 de junio, Día Internacional del Orgullo LGBTIQ+.​ Es el evento celebrado por…',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196004,'08003','Orgullo de Barcelona','lgtbi','lgtbi_wiki','El Orgullo de Barcelona (en catalán, Orgull de Barcelona), también llamado Pride Barcelona, es la manifestación que se celebra de forma anual en Barcelona, España, en conmemoración del Día Internacional del Orgullo LGBT. La marcha es organizada por la Asociación Catalana de Empresas para Gays y Lesbianas en…',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196005,'29901','Orgullo LGTB Torremolinos','lgtbi','lgtbi_wiki','El Orgullo LGTBI de Torremolinos es una celebración anual en defensa de los derechos del colectivo LGTBI que tiene lugar en la localidad andaluza de Torremolinos, en la Costa del Sol, a finales de mayo o principios de junio. En pocas ediciones, se ha convertido en uno de los orgullos más multitudinarios del sur de…',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_LGTB_Torremolinos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196006,'46250','Orgullo de Valencia','lgtbi','lgtbi_wiki','El Orgullo de Valencia es una fiesta reivindicativa que se celebra en junio en la capital de la Comunidad Valenciana (España), en el marco del Día Internacional del Orgullo LGBT del 28 de junio.​ La entidad Lambda organiza muchas de las marchas y manifestaciones, que se llevan celebrando en la ciudad desde 1979.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Valencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196007,'03003','Orgullo de Alicante','lgtbi','lgtbi_wiki','El Orgullo de Alicante (oficialmente Orgullo Alacant)​ es un acto reivindicativo, ciudadano, social y participativo que tiene lugar anualmente en Alicante y que se celebra el tercer fin de semana del mes de julio desde 2011.',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Alicante');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196008,'18087','Orgullo de Granada','lgtbi','lgtbi_wiki','El Orgullo Granada es un evento que ocurre anualmente en la ciudad de Granada (España) con el objetivo de celebrar el Mes del Orgullo LGBT+, generalmente durante el mes de junio de cada año, si bien las principales movilizaciones ocurren el último fin de semana de ese mes. Además de la marcha del orgullo LGBT+…',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196009,'06006','Fiesta de Los Palomos (Badajoz)','lgtbi','lgtbi_wiki','La Fiesta de Los Palomos (también referenciado como L@s Palom@s), conocida en sus primeras ediciones como Caravana de Palomos, es una popular fiesta que se celebra en la ciudad de Badajoz (España), desde 2011, en favor de la igualdad y la diversidad del colectivo LGTBI, teniendo como centro neurálgico de la fiesta…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Los_Palomos_(Badajoz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196010,'28079','Mr. Gay Pride España','lgtbi','lgtbi_wiki','Mr. Gay España es el certamen LGTBIQ+ más importante y libre de España. Fue creado en el año 2008.',NULL,NULL,'https://es.wikipedia.org/wiki/Mr._Gay_Pride_España');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196011,'33024','Festival de Cine LGBTIQ - Asturias','lgtbi','lgtbi_wiki','El Festival de Cine LGBTI de Asturias (antes Festival de cine LGTBIQ) se creó como un impulso por parte del Centro Cultural Internacional Oscar Niemeyer para continuar reforzando en dicha región la visibilidad del colectivo de lesbianas, gais, bisexuales, transexuales, intersexuales y queer.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_LGBTIQ_-_Asturias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196012,'41091','Festival de Cine Lésbico y Gai de Andalucía','lgtbi','lgtbi_wiki','El Festival de Cine Lésbico, Gai, bisexual y transexual de Andalucía, también llamado AndaLesGai, es un festival cinematográfico de temática LGBT celebrado anualmente en Andalucía desde el año 2006. Se trata del único festival de cine LGTB en la comunidad autónoma. El festival se desarrolla principalmente en…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Lésbico_y_Gai_de_Andalucía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196013,'35016','Festival de cine Gay y Lésbico de Canarias','lgtbi','lgtbi_wiki','El Festival de cine Gay y Lésbico de Canarias, más conocido como Festival del Sol, inicia su andadura en el año 2006 en Las Palmas de Gran Canaria (Gran Canaria, España) y desde el año 2007, también se celebra conjuntamente en Santa Cruz de Tenerife (Tenerife). Se trata de un festival joven, que recoge la herencia…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_cine_Gay_y_Lésbico_de_Canarias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(196014,'35019','Playa del Inglés','lgtbi','lgtbi_wiki','La playa del Inglés comprende la zona de costa situada al este de las Dunas de Maspalomas, desde Punta Maspalomas hasta la playa de San Agustín, en el sur de Gran Canaria, perteneciente al archipiélago canario (España),​ y da nombre a una de las urbanizaciones turísticas más importantes de la isla. Entre estas dos…',27.75,-15.58056,'https://es.wikipedia.org/wiki/Playa_del_Inglés');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion) VALUES(196015,'35019','Centro Comercial Yumbo y ambiente de Maspalomas','lgtbi','lgtbi_curado','Epicentro del ambiente LGTBI de Gran Canaria: decenas de bares, terrazas y clubs concentrados en el Yumbo, a un paso de las dunas de Maspalomas y de la playa. Uno de los destinos gais más consolidados de Europa, con el Maspalomas Pride cada mayo.');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion) VALUES(196016,'08023','Ambiente de Sitges y Carnaval','lgtbi','lgtbi_curado','Sitges es desde hace décadas uno de los destinos LGTBI de referencia en el Mediterráneo: calles de ambiente junto al mar, playas para todos los públicos y un carnaval multitudinario que llena el pueblo cada febrero.');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion) VALUES(196017,'29901','La Nogalera y ambiente de Torremolinos','lgtbi','lgtbi_curado','La Nogalera concentra el ambiente LGTBI de Torremolinos, pionero del turismo gay en España desde los años 60. Bares, clubs y terrazas a pocos minutos de la playa, con el Pride de Torremolinos cada junio.');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion) VALUES(196018,'03007','Ambiente LGTBI de Benidorm','lgtbi','lgtbi_curado','Benidorm mantiene una escena LGTBI muy activa durante todo el año, concentrada en el casco antiguo: bares de ambiente, espectáculos y el Benidorm Pride a principios de septiembre.');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion) VALUES(196019,'07026','Escena LGTBI de Ibiza','lgtbi','lgtbi_curado','Ibiza combina sus clubs legendarios con una escena LGTBI histórica concentrada en el puerto y la calle de la Virgen de Dalt Vila, además de la playa de Es Cavallet como referencia.');

